pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 prePot;
        try c.pot() returns (uint256 __r) { prePot = __r; } catch { return; }
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 postPot;
        try c.pot() returns (uint256 __r) { postPot = __r; } catch { return; }
        uint expectedPotOnSuccess = amount == 10 ? (postPot == 0 || postPot <= 10 ? 1 : 0) : 0;
        uint expectedPotOnRevert = amount == 10 ? 0 : (postPot == prePot ? 1 : 0);
        assertTrue(amount == 10 ? (!reverted && expectedPotOnSuccess == 1) : (reverted && expectedPotOnRevert == 1));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
